v:[['غِيَابٌ','absence'],['الصَّفُّ','class, year'],['لِأُخْبِرَكِ','to tell you (f)'],['لَنْ يَأْتِيَ','he will not come'],['مَوْعِدٌ','appointment'],['العُيُونُ','eyes'],['تُرْسِلِي','(that) you (f) send']],
